// NODE 2: DAILY LOGIC FILTER
// ===========================
const rows = $input.all().map(i => i.json);

// Configuration
const IS_TEST_MODE = true;
const TEST_DATE = "Tuesday, June 24, 2025";

// Date Setup
const todayOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
const realToday = new Date().toLocaleDateString('en-US', todayOptions);
const targetDate = IS_TEST_MODE ? TEST_DATE : realToday;

// Filter Logic
const dailyJobs = rows.filter(r => {
    const rowDate = (r["Scheduled Cleaning Day"] || "").trim();
    const status = (r["Status"] || "").toLowerCase();

    const isToday = rowDate === targetDate;
    const isReclean = status.includes("reclean") || status.includes("re-clean");

    return isToday || isReclean;
});

return dailyJobs.map(job => ({
    json: job 
}));

// NODE 1: STATS CALCULATOR (Counts Multiple Cleanings)
// ====================================================
const allRows = $input.all().map(i => i.json);

// 1. Initialize Counters
let totalUnits = allRows.length;
let cleanEventsProject = 0;  // Counts every time a unit was cleaned (1st + 2nd)
let carpetEventsProject = 0; // Counts every time a unit was carpeted (1st + 2nd)
let uniqueCleaned = 0;       // Counts unique units finished (for "Remaining" calc)
let uniqueCarpet = 0;

// 2. Scan the whole project
allRows.forEach(row => {
    // A. Count Cleaning Events (Check if dates exist)
    const date1 = row["Date Cleaned "] || "";
    const date2 = row["Second Cleaning, IF applicable"] || "";

    if (date1.length > 2) cleanEventsProject++;
    if (date2.length > 2) cleanEventsProject++;

    // B. Count Carpet Events
    const cDate1 = row["Date Carpet Cleaned"] || "";
    const cDate2 = row["Second Carpet Cleaning, If applicable"] || "";

    if (cDate1.length > 2) carpetEventsProject++;
    if (cDate2.length > 2) carpetEventsProject++;

    // C. Track Unique Completions (For the Pie Chart "Not Done" slice)
    if (row["Cleaning Complete "] === true) uniqueCleaned++;
    if (row["Carpet Cleaned"] === true) uniqueCarpet++;
});

// 3. Package the stats
const stats = {
    total: totalUnits,
    // For "Total Project Work" (Cleaners get paid for this)
    cleaned_project_total: cleanEventsProject,
    carpet_project_total: carpetEventsProject,
    // For "Remaining Work" (Managers care about this)
    remaining_clean: totalUnits - uniqueCleaned,
    remaining_carpet: totalUnits - uniqueCarpet,
    unique_clean: uniqueCleaned,
    unique_carpet: uniqueCarpet
};

// 4. Attach to all rows
return allRows.map(row => ({
    json: { ...row, _project_stats: stats }
}));

// NODE 3: HTML GENERATOR (Manager, Cleaner, AND Carpet)
// ======================================================
const jobs = $input.all().map(i => i.json);
const stats = jobs.length > 0 ? jobs[0]._project_stats : { total: 0 };

// 1. HELPERS: Charts & Breakdowns
function getChart(label, done, total) {
    const config = {
        type: 'pie',
        data: {
            labels: [label, 'Remaining'],
            datasets: [{ data: [done, Math.max(0, total - done)], backgroundColor: ['#4caf50', '#e0e0e0'] }]
        },
        options: { plugins: { datalabels: { display: true, color: 'white', font: { weight: 'bold' } } } }
    };
    return `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(config))}&w=200&h=120`;
}

function getBreakdown(jobList) {
    const counts = {};
    jobList.forEach(j => {
        const type = j["Unit Type"] || "Unknown";
        counts[type] = (counts[type] || 0) + 1;
    });
    return Object.entries(counts).map(([type, count]) => `${count} ${type}`).join(', ');
}

// 2. CALCULATE TODAY'S STATS (Separately!)
let todayClean = 0;
let todayCarpet = 0;

jobs.forEach(j => {
    if (j["Cleaning Complete "] === true) todayClean++;
    if (j["Carpet Cleaned"] === true) todayCarpet++;
});

// 3. GENERATE CHARTS
const cleanChart = getChart("Cleaned", stats.cleaned_project_total, stats.total);
const carpetChart = getChart("Carpet", stats.carpet_project_total, stats.total);

// 4. BUILD TABLE ROWS
const tableStyle = `width: 100%; border-collapse: collapse; font-family: Arial, 13px; margin-top: 10px;`;
const tdStyle = `padding: 8px; border: 1px solid #ddd;`;

let managerRows = "";
let cleanerRows = "";
let carpetRows = ""; // <--- NEW separate list

jobs.forEach(job => {
    const cleanCheck = job["Cleaning Complete "] === true ? "✅" : "⬜";
    const carpetCheck = job["Carpet Cleaned"] === true ? "✅" : "⬜";
    const status = (job.Status || "").toLowerCase();
    const color = status.includes("occupied") || status.includes("reclean") ? "#d9534f" : "black";

    // Common Columns
    const unitCols = `<td style="${tdStyle}"><b>${job.Unit}</b></td><td style="${tdStyle}">${job["Unit Type"]}</td>`;

    // Manager (Everything)
    managerRows += `<tr>${unitCols}
        <td style="${tdStyle} color: ${color}; font-weight: bold;">${job.Status || "-"}</td>
        <td style="${tdStyle} text-align:center;">${cleanCheck} / ${carpetCheck}</td>
        <td style="${tdStyle}">${job.Notes || ""}</td>
    </tr>`;

    // Cleaner (Focus on Cleaning Checkbox)
    cleanerRows += `<tr>${unitCols}
        <td style="${tdStyle} text-align:center;">${cleanCheck}</td>
        <td style="${tdStyle}">${job.Notes || ""}</td>
    </tr>`;

    // Carpet (Focus on Carpet Checkbox)
    carpetRows += `<tr>${unitCols}
        <td style="${tdStyle} text-align:center;">${carpetCheck}</td>
        <td style="${tdStyle}">${job.Notes || ""}</td>
    </tr>`;
});

// 5. ASSEMBLE REPORTS
// ---------------------------------------------------------

// A. MANAGER REPORT (2.1)
const manager_html = `
<div style="font-family: Arial;">
    <h2 style="color: #2c3e50;">Property Manager Daily Report</h2>
    <div style="background: #f8f9fa; padding: 10px; border: 1px solid #ddd; display: flex; gap: 20px;">
        <div style="text-align:center;"><img src="${cleanChart}" /><br><small>Cleaning</small></div>
        <div style="text-align:center;"><img src="${carpetChart}" /><br><small>Carpet</small></div>
        <div style="font-size: 13px;">
            <b>TODAY:</b> ${todayClean} Clean | ${todayCarpet} Carpet<br>
            <b>REMAINING:</b> ${stats.remaining_clean} Units
        </div>
    </div>
    <table style="${tableStyle}">
        <tr style="background:#eee;"><th>Unit</th><th>Type</th><th>Status</th><th>Clean/Carpet</th><th>Notes</th></tr>
        ${managerRows}
    </table>
</div>`;

// B. CLEANER REPORT (2.2)
const cleaner_html = `
<div style="font-family: Arial;">
    <h2 style="color: #27ae60;">🧹 Cleaner Task List</h2>
    <div style="background: #e9f7ef; padding: 15px; border-left: 5px solid #27ae60;">
        <b>Today's Target:</b> ${todayClean} Units<br>
        <b>Project Total:</b> ${stats.cleaned_project_total} Cleaned<br>
        <b>Remaining:</b> ${stats.remaining_clean} Units<br>
        <b>Breakdown:</b> ${getBreakdown(jobs)}
    </div>
    <table style="${tableStyle}">
        <tr style="background:#eee;"><th>Unit</th><th>Type</th><th>Cleaned?</th><th>Notes</th></tr>
        ${cleanerRows}
    </table>
</div>`;

// C. CARPET REPORT (2.3) - <--- THIS IS THE NEW ONE
const carpet_html = `
<div style="font-family: Arial;">
    <h2 style="color: #8e44ad;">🧼 Carpet Technician Report</h2>
    <div style="background: #f4ecf7; padding: 15px; border-left: 5px solid #8e44ad;">
        <b>Today's Target:</b> ${todayCarpet} Units<br>
        <b>Project Total:</b> ${stats.carpet_project_total} Carpeted<br>
        <b>Remaining:</b> ${stats.remaining_carpet} Units<br>
        <b>Breakdown:</b> ${getBreakdown(jobs)}
    </div>
    <table style="${tableStyle}">
        <tr style="background:#eee;"><th>Unit</th><th>Type</th><th>Carpeted?</th><th>Notes</th></tr>
        ${carpetRows}
    </table>
</div>`;

return [{
    json: {
        date: new Date().toDateString(),
        manager_email_body: manager_html,
        cleaner_email_body: cleaner_html,
        carpet_email_body: carpet_html   // <--- Now you have this!
    }
}];

// NODE 2: WEEKLY FILTER & FEES (Logic)
// =====================================
const allRows = $input.all().map(i => i.json);

// --- DEMO MODE SETTINGS ---
const today = new Date("2025-06-30"); // DEMO DATE
const sevenDaysAgo = new Date(today);
sevenDaysAgo.setDate(today.getDate() - 7);
// --------------------------

function isThisWeek(dateStr) {
    if (!dateStr) return false;
    const d = new Date(dateStr);
    return !isNaN(d.getTime()) && d >= sevenDaysAgo && d <= today;
}

// 1. Filter for Weekly Jobs
const weeklyJobs = [];
let totalCleanerFee = 0;
let totalPropertyFee = 0;

allRows.forEach(row => {
    const cleanDate = row["Date Cleaned "];
    const carpetDate = row["Date Carpet Cleaned"];

    if (isThisWeek(cleanDate) || isThisWeek(carpetDate)) {
        weeklyJobs.push(row);

        // 2. Calculate Money (Remove $ and ,)
        const cFee = parseFloat((row["Excessive cleaning fee (Cleaners Pay)"] || "0").toString().replace(/[$,]/g, ''));
        const pFee = parseFloat((row["Excessive cleaning fee (Property Charge)"] || "0").toString().replace(/[$,]/g, ''));

        if (!isNaN(cFee)) totalCleanerFee += cFee;
        if (!isNaN(pFee)) totalPropertyFee += pFee;
    }
});

// 3. Prepare Data for Next Node
// We pass the "Filtered List" and the "Money Stats"
// We also keep the "Project Stats" from Node 1
return [{
    json: {
        date_start: sevenDaysAgo.toDateString(),
        date_end: today.toDateString(),
        jobs: weeklyJobs,
        financials: {
            cleaner_fee: totalCleanerFee.toFixed(2),
            property_fee: totalPropertyFee.toFixed(2),
            count: weeklyJobs.length
        },
        project_stats: allRows[0]._project_stats // Grab from backpack
    }
}];

// NODE 1: PROJECT STATS (The Big Picture)
// ========================================
const allRows = $input.all().map(i => i.json);

let projectTotalCleaned = 0;
let totalUnits = allRows.length;

// Count how many are done (regardless of date)
allRows.forEach(row => {
    if ((row["Date Cleaned "] || "").length > 2) {
        projectTotalCleaned++;
    }
});

// Calculate Remaining
const remaining = totalUnits - projectTotalCleaned;

// Attach these stats to EVERY row (The Backpack method)
return allRows.map(row => ({
    json: {
        ...row,
        _project_stats: {
            total: totalUnits,
            cleaned: projectTotalCleaned,
            remaining: remaining
        }
    }
}));

// NODE 3A: HTML SUMMARY GENERATOR
// ===============================
const data = $input.first().json;
const jobs = data.jobs;
const financials = data.financials;
const project = data.project_stats;

// 1. CALCULATE BREAKDOWN
const typeCounts = {};
jobs.forEach(j => { typeCounts[j["Unit Type"]] = (typeCounts[j["Unit Type"]] || 0) + 1; });
const breakdown = Object.entries(typeCounts).map(([k,v]) => `${v} ${k}`).join(', ');

// 2. GENERATE HTML
const emailHTML = `
<div style="font-family: Arial; color: #333;">
    <h2 style="color: #2c3e50;">WEEKLY FINANCIAL REPORT</h2>
    <p><b>Period:</b> ${data.date_start} to ${data.date_end}</p>
    <div style="background: #f4f6f7; padding: 15px; border: 1px solid #ddd; border-radius: 5px;">
        <h3>💰 Weekly Financials</h3>
        <table style="width: 100%; text-align: left;">
            <tr><th style="width:200px">Units Completed:</th><td>${financials.count}</td></tr>
            <tr><th>Cleaner Fees:</th><td>$${financials.cleaner_fee}</td></tr>
            <tr><th>Property Charges:</th><td>$${financials.property_fee}</td></tr>
        </table>
    </div>
    <div style="margin-top: 15px;">
        <b>Project Totals:</b> ${project.cleaned} Done | ${project.remaining} Remaining<br>
        <b>This Week:</b> ${breakdown}
    </div>
    <p><i>The detailed QuickBooks CSV file is attached.</i></p>
</div>
`;

return {
    subject: `Weekly Finance Report - ${data.date_end}`,
    email_body: emailHTML
};

// NODE 3B: CSV ROW PREP (Flat Data)
// ================================
const data = $('Logic1').first().json;

// This returns 127 clean items immediately
return data.jobs.map(row => ({
    json: {
        "Unit": row.Unit,
        "Unit Type": row["Unit Type"],
        "Date Cleaned": row["Date Cleaned "],
        "Status": row.Status,
        "Fee (Cleaner)": row["Excessive cleaning fee (Cleaners Pay)"] || "0",
        "Fee (Property)": row["Excessive cleaning fee (Property Charge)"] || "0",
        "Notes": (row.Notes || "").replace(/\n/g, " ")
    }
}));
